with e as(select (v->>'order')::int ord,(v->>'period')::int per,v->>'clock' clock,v->>'type' typ,v->>'text' txt,v->'participants' ids,case when v->>'scoring_play'='true' then (v->>'score_value')::int end pts,(v->>'home_score')::int h,(v->>'away_score')::int a from nba_pbp_snapshots_v1 p cross join lateral jsonb_array_elements(payload->'data') v where provider_game_id=GAME), roles as(select per,id,role,pts,typ,txt from e cross join lateral jsonb_array_elements_text(ids) with ordinality as person(id,role)), agg as(select per,id,sum(case when role=1 then pts end) pts,count(*) filter(where role=1 and pts=3) threes,count(*) filter(where role=1 and typ in ('Defensive Rebound','Offensive Rebound') and txt not ilike '%team rebound%') reb,count(*) filter(where role=2 and pts>0 and txt ilike '%assists)%') ast,count(*) filter(where role=2 and txt ilike '%steals)%') stl,count(*) filter(where role=2 and txt ilike '% blocks %') blk,count(*) filter(where role=1 and txt ilike '%turnover%') tov,bool_or(typ='Substitution' or pts>0 or typ in ('Jumpball','Defensive Rebound','Offensive Rebound') or txt ilike '%misses %' or txt ilike '% blocks %') active from roles group by per,id) select (select count(*)=count(distinct ord) from e) unique_order,(select count(*) from e where typ='End Game') ended,(select jsonb_build_array(typ,per,clock,h,a) from e order by ord desc limit 1) terminal,(select jsonb_agg(jsonb_build_array(per,h,a) order by per) from e where typ='End Period') ends,(select jsonb_agg(jsonb_build_array(per,id,coalesce(pts,0),reb,ast,threes,stl,blk,tov,active)) from agg) rows
